const e=value=>String(value).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const external='target="_blank" rel="noopener noreferrer"';
function reading(item,index){return `<article class="science-reading science-reading--${item.id}"><p class="science-reading-meta"><span>${e(item.topic)}</span><span>0${index+1}</span></p><a href="${e(item.href)}" ${external} aria-label="${e(item.headline)} — ${e(item.source)}, ${item.year}. Abrir fonte"><h3>${e(item.headline)}<span class="science-link-arrow" aria-hidden="true">↗</span></h3><span class="science-reading-source">${e(item.source)} <span>·</span> ${item.year} <span class="science-source-action">Ler fonte ↗</span></span></a></article>`;}
function institution(item){return `<a class="science-institution" href="${e(item.href)}" ${external}><span>${e(item.name)}</span><small>${e(item.detail)} <b aria-hidden="true">↗</b></small></a>`;}
export function renderScienceSection(){return `<section class="science-section" id="science" aria-labelledby="science-title"><div class="science-heading"><p class="science-kicker"><svg class="science-spark" viewBox="0 0 32 32" fill="none" aria-hidden="true"><text x="16" y="16" text-anchor="middle" dominant-baseline="central" fill="currentColor" font-family="Roobert,Geist,Arial,sans-serif" font-size="24" font-weight="550" letter-spacing="0" textLength="30" lengthAdjust="spacingAndGlyphs">OS</text></svg> UM MUNDO DE DESCOBERTAS</p><h2 id="science-title">A ciência avança no mundo.<br><span>Sua trajetória começa aqui.</span></h2><p class="science-intro">Novas perguntas. Novas perspectivas.<br> Conhecimento para ampliar o seu próximo passo.</p></div><div class="science-composition"><div class="science-side science-side--left">${reading(scienceReadings[0],0)}${reading(scienceReadings[2],2)}</div><figure class="science-center"><figcaption class="science-reference-label">Referências da pesquisa mundial</figcaption><div class="science-institution-row science-institution-row--top">${scienceInstitutions.slice(0,2).map(institution).join('')}</div><div class="science-sphere" data-science-globe><img data-globe-fallback src="/assets/science-globe/fallback.svg" alt="Globo pontilhado com o Brasil destacado em rosa" width="800" height="800" loading="lazy"><canvas data-globe-canvas aria-hidden="true"></canvas><button class="science-globe-toggle" data-globe-toggle type="button" aria-label="Pausar rotação do globo" aria-pressed="false" hidden><span data-globe-toggle-icon aria-hidden="true">Ⅱ</span><span data-globe-toggle-text>Pausar rotação</span></button></div><p class="science-globe-hint" id="science-globe-hint"><span class="science-hint-pointer">Arraste para girar · use também as teclas de seta</span><span class="science-hint-touch">Deslize na horizontal para girar</span><span aria-hidden="true">↔</span></p><div class="science-institution-row science-institution-row--bottom">${scienceInstitutions.slice(2).map(institution).join('')}</div></figure><div class="science-side science-side--right">${reading(scienceReadings[1],1)}${reading(scienceReadings[3],3)}</div></div><div class="science-foot"><p>Referências editoriais independentes.<br>Sem vínculo institucional com a THE MED.</p><a href="/modulos/pesquisa/" class="science-cta"><span>Encontre seu caminho<br><strong>na pesquisa.</strong></span><span class="science-cta-arrow" aria-hidden="true">↗</span></a><span class="science-coordinate" aria-hidden="true">DO BRASIL<br>PARA O MUNDO <span>↗</span></span></div></section>`;}
